    essentiel: [
      { titre: "Une palette courte", texte: "Une couleur principale, une couleur d'accent, un fond clair et un texte foncé. Quatre à cinq couleurs suffisent." },
      { titre: "Le contraste d'abord", texte: "Le texte doit rester lisible sur son fond. Vérifiez le contraste avec un outil dédié : c'est aussi une question d'accessibilité." },
      { titre: "Deux polices", texte: "Une pour les titres, une pour le texte. Choisissez des polices lisibles et dont la licence autorise l'usage commercial." },
    ],
    script: [
      { partie: "Hook", ecran: "Le même site en trois palettes ; l'impression change complètement.", voix: "Le même site, avec trois palettes de couleurs différentes. Dans le premier cas, il inspire la confiance. Dans le deuxième, l'énergie. Dans le troisième, le calme. Les couleurs ne sont pas anodines : elles communiquent avant même que vous ayez lu un mot." },
      { partie: "Objectif", ecran: "Titre et objectifs.", voix: "Dans cette leçon, vous allez construire une palette simple, vérifier qu'elle est lisible, et choisir deux typographies qui vont bien ensemble." },
      { partie: "Explication", ecran: "Une palette de 5 pastilles étiquetées : principale, accent, fond, texte, secondaire.", voix: "Une palette de marque n'a pas besoin d'être compliquée. Une couleur principale, qui est la plus reconnaissable. Une couleur d'accent, pour les boutons et les éléments importants. Un fond clair. Une couleur de texte foncée. Et éventuellement une couleur secondaire. Quatre à cinq couleurs suffisent, et c'est plus facile de rester cohérent. Chaque couleur transmet une impression : le vert évoque souvent le naturel et le calme, le bleu la confiance, le orange l'énergie. Mais ce sont des tendances, pas des règles : l'important est la cohérence avec votre positionnement." },
      { partie: "Explication", ecran: "Deux textes : l'un contrasté, l'autre pâle sur fond clair, illisible.", voix: "Un point essentiel : le contraste. Un texte gris clair sur fond blanc est joli sur une maquette, mais illisible pour beaucoup de gens, notamment dans la lumière du jour ou pour les personnes malvoyantes. Il existe des outils gratuits qui mesurent le contraste entre deux couleurs et vous disent s'il est suffisant. Utilisez-les systématiquement. Pour les polices, deux suffisent : une pour les titres, une pour le texte courant. Vérifiez la licence : certaines polices ne sont pas gratuites pour un usage commercial." },
      { partie: "Exemple concret", ecran: "Palette de Maison Verdure : vert profond, vert tendre, crème, brun doux, corail.", voix: "Léa choisit un vert profond comme couleur principale, un vert tendre secondaire, un fond crème, un brun doux pour le texte, et une touche de corail pour les boutons. Elle vérifie le contraste du texte brun sur le fond crème : il est suffisant. Pour les polices, elle choisit une police arrondie et chaleureuse pour les titres, et une police très lisible pour les textes. Tout cela évoque le naturel et la bienveillance, exactement ses trois adjectifs." },
      { partie: "Démonstration", ecran: "CAPTURE RÉELLE À FILMER : l'assistant propose 3 palettes avec codes couleur ; vérification du contraste dans un outil en ligne ; choix de polices dans une bibliothèque de polices libres.", voix: "Je demande à l'assistant : propose trois palettes de cinq couleurs avec leurs codes, pour une marque qui est chaleureuse, naturelle et rassurante. J'obtiens des suggestions. Je choisis une palette, puis je vérifie le contraste entre mon texte et mon fond dans un outil dédié. Je corrige si nécessaire. Ensuite, je consulte une bibliothèque de polices libres, et je choisis deux polices. Je note leur licence. L'IA propose des idées, mais c'est moi qui regarde le résultat à l'écran et qui juge." },
      { partie: "Erreurs fréquentes", ecran: "Trois cartes corail : « Trop de couleurs », « Texte illisible », « Polices sans licence commerciale ».", voix: "Les erreurs. Utiliser trop de couleurs et perdre toute cohérence. Choisir un texte illisible parce que « c'est joli ». Et utiliser une police sans vérifier sa licence : un usage commercial non autorisé peut vous poser des problèmes. Quand vous téléchargez une police, lisez toujours ses conditions d'utilisation." },
      { partie: "Mission", ecran: "Encart « À vous » : palette de 5 couleurs avec codes, contraste vérifié, 2 polices avec licence.", voix: "Votre mission : choisissez une palette de quatre à cinq couleurs, avec leurs codes. Vérifiez le contraste du texte sur le fond. Choisissez deux polices et notez leur licence. Enregistrez le tout : il servira pour votre mini-charte et votre site." },
      { partie: "Transition", ecran: "Titre de la leçon suivante : « Créer son logo avec l'IA ».", voix: "Il ne manque plus que le symbole de votre marque : le logo. C'est l'objet de la prochaine leçon." },
    ],
    exercice: { titre: "Votre palette et vos polices", consigne: "Choisissez 4 à 5 couleurs (avec leurs codes), vérifiez le contraste du texte et choisissez deux polices avec leur licence.", champs: [{ label: "Ma palette (rôle et code de chaque couleur)" }, { label: "Contraste vérifié (texte sur fond) : résultat" }, { label: "Police des titres et licence" }, { label: "Police du texte et licence" }] },
    prompt: { titre: "Propositions de palettes", texte: "Ma marque est : [3 ADJECTIFS]. Mon public : [PUBLIC].\nPropose 3 palettes de 5 couleurs avec leurs codes hexadécimaux et le rôle de chacune (principale, accent, fond, texte, secondaire).\nPrécise que je dois vérifier le contraste du texte avec un outil dédié.", conseil: "Ne jugez pas une palette sur sa description : regardez-la à l'écran." },
    verifier: ["La palette tient en cinq couleurs ou moins", "Le contraste du texte sur le fond est suffisant", "La licence des polices autorise l'usage commercial"],
    quiz: [
      { question: "Combien de couleurs pour une palette de marque ?", choix: ["Quatre à cinq suffisent", "Une dizaine", "Une seule"], bonne: 0, explication: "Une palette courte reste cohérente." },
      { question: "Pourquoi vérifier le contraste ?", choix: ["Pour la lisibilité et l'accessibilité", "Pour le référencement uniquement", "Pour le prix"], bonne: 0, explication: "Un texte contrasté est lisible pour tous." },
      { question: "Que vérifier avant d'utiliser une police ?", choix: ["Sa licence d'usage commercial", "Son nombre de lettres", "Sa couleur"], bonne: 0, explication: "Certaines polices ne sont pas libres pour un usage commercial." },
    ],
